var rock=UnityEngine.Resources.FindObjectsOfTypeAll<UnityEngine.GameObject>().First(g=>g.name=="Nature - Rock_01");
var plant=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.Renderer>(true)).First(r=>r.name=="Sprout").gameObject;
var cameraObject=new UnityEngine.GameObject("Material review camera"){hideFlags=UnityEngine.HideFlags.HideAndDontSave};var camera=cameraObject.AddComponent<UnityEngine.Camera>();camera.enabled=false;camera.fieldOfView=48;camera.nearClipPlane=0.001f;camera.farClipPlane=10;camera.clearFlags=UnityEngine.CameraClearFlags.SolidColor;camera.backgroundColor=new UnityEngine.Color(0.58f,0.63f,0.68f);camera.cullingMask=1<<31;
var target=new UnityEngine.RenderTexture(1000,800,24);camera.targetTexture=target;var texture=new UnityEngine.Texture2D(1000,800,UnityEngine.TextureFormat.RGB24,false);var previous=UnityEngine.RenderTexture.active;
try{foreach(var source in new[]{rock,plant}){var specimen=UnityEngine.Object.Instantiate(source);specimen.hideFlags=UnityEngine.HideFlags.HideAndDontSave;specimen.transform.position=new UnityEngine.Vector3(1000,0,1000);specimen.transform.localScale=source.transform.lossyScale;
try{foreach(var transform in specimen.GetComponentsInChildren<UnityEngine.Transform>(true))transform.gameObject.layer=31;foreach(var collider in specimen.GetComponentsInChildren<UnityEngine.Collider>())collider.enabled=false;foreach(var lod in specimen.GetComponentsInChildren<UnityEngine.LODGroup>())lod.enabled=false;
var renderers=specimen.GetComponentsInChildren<UnityEngine.Renderer>();var bounds=renderers[0].bounds;foreach(var renderer in renderers)bounds.Encapsulate(renderer.bounds);float size=System.Math.Max(bounds.size.x,System.Math.Max(bounds.size.y,bounds.size.z));camera.transform.position=bounds.center+new UnityEngine.Vector3(0.5f,1.05f,-1.7f)*size;camera.transform.LookAt(bounds.center);camera.Render();UnityEngine.RenderTexture.active=target;texture.ReadPixels(new UnityEngine.Rect(0,0,1000,800),0,0);texture.Apply();System.IO.File.WriteAllBytes("Docs/Validation/"+(source==rock?"PastelStoneReview":"PastelPlantReview")+".png",texture.EncodeToPNG());}finally{UnityEngine.Object.DestroyImmediate(specimen);}}}
finally{UnityEngine.RenderTexture.active=previous;camera.targetTexture=null;UnityEngine.Object.DestroyImmediate(cameraObject);UnityEngine.Object.DestroyImmediate(target);UnityEngine.Object.DestroyImmediate(texture);}
return new{captured=true};

